def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Endgame: always defect in the last two rounds
    if n >= 98:
        return 'D'

    opp_defects = 0
    my_defects = 0
    for me, op in history:
        if op == 'D':
            opp_defects += 1
        if me == 'D':
            my_defects += 1

    if opp_defects == 0:
        return 'C'

    defect_rate = opp_defects / n
    last_me, last_op = history[-1]

    if last_op == 'D':
        if last_me == 'C':
            # Unprovoked defection: punish firmly
            if defect_rate > 0.6:
                return 'D'
            else:
                if rng.random() < 0.25:
                    return 'C'
                return 'D'
        else:
            # We defected last round, they retaliated: try to restore cooperation
            if defect_rate > 0.6:
                return 'D'
            else:
                if rng.random() < 0.5:
                    return 'C'
                return 'D'
    else:
        # Opponent cooperated
        if defect_rate < 0.3:
            return 'C'
        else:
            if rng.random() < 0.85:
                return 'C'
            return 'D'
